// DOBRZE: prehashowanie SHA-256 PRZED BCrypt, eliminuje limit 72 bajtow
String prehash(String password) throws NoSuchAlgorithmException {
    byte[] hash = MessageDigest.getInstance("SHA-256").digest(password.getBytes());
    return Base64.getEncoder().encodeToString(hash); // stala dlugosc, zawsze ponizej 72 bajtow
}

